gMR(){return"\u067e\u0631\u0627\u0646\u06d2 \u0633\u0627\u0641\u0679 \u0648\u06cc\u0626\u0631 \u0633\u06d2 \u062f\u0631\u0622\u0645\u062f \u06a9\u0631\u06cc\u06ba"},
gMS(){return"Manager.io \u0633\u06d2 \u0627\u067e\u0646\u0627 \u0688\u06cc\u0679\u0627 \u0644\u0627\u0626\u06cc\u06ba"},
